    def create(self):
        return PriceCalculator()

class PriceCalculator:
    def __init__(self, currency='USD', rounding=None, debug=False):
        self.currency = currency
    def total(self, items):
        # loop over items and add prices
        result = 0
        for item in items:
            result = result + item['price']
        return result

def get_total(items):
    return PriceCalculatorFactory().create().total(items)
